const starNoEmpty = qmark + '+?'

// remove the \ chars that we added if we end up doing a nonmagic compare
// const deslash = (s: string) => s.replace(/\\(.)/g, '$1')

let ID = 0
export class AST {
  type: ExtglobType | null
  readonly #root: AST

  #hasMagic?: boolean
  #uflag: boolean = false
  #parts: (string | AST)[] = []
  #parent?: AST
  #parentIndex: number
  #negs: AST[]
  #filledNegs: boolean = false
  #options: MinimatchOptions
  #toString?: string
  // set to true if it's an extglob with no children
  // (which really means one child of '')
  #emptyExt: boolean = false
  id = ++ID

  get depth(): number {
    return (this.#parent?.depth ?? -1) + 1
  }

  [Symbol.for('nodejs.util.inspect.custom')]() {
    return {
      '@@type': 'AST',
      id: this.id,
      type: this.type,
      root: this.#root.id,
      parent: this.#parent?.id,
      depth: this.depth,
      partsLength: this.#parts.length,
      parts: this.#parts,
    }
  }

  constructor(
    type: ExtglobType | null,
    parent?: AST,
    options: MinimatchOptions = {},
  ) {
    this.type = type
    // extglobs are inherently magical
    if (type) this.#hasMagic = true
    this.#parent = parent
    this.#root = this.#parent ? this.#parent.#root : this
    this.#options = this.#root === this ? options : this.#root.#options
    this.#negs = this.#root === this ? [] : this.#root.#negs
    if (type === '!' && !this.#root.#filledNegs) this.#negs.push(this)
    this.#parentIndex = this.#parent ? this.#parent.#parts.length : 0
  }

  get hasMagic(): boolean | undefined {
    /* c8 ignore start */
    if (this.#hasMagic !== undefined) return this.#hasMagic
    /* c8 ignore stop */
    for (const p of this.#parts) {
      if (typeof p === 'string') continue
      if (p.type || p.hasMagic) return (this.#hasMagic = true)
    }
    // note: will be undefined until we generate the regexp src and find out
    return this.#hasMagic
  }

  // reconstructs the pattern
  toString(): string {
    return (
      this.#toString !== undefined ? this.#toString
      : !this.type ?
        (this.#toString = this.#parts.map(p => String(p)).join(''))
      : (this.#toString =
          this.type +
          '(' +
          this.#parts.map(p => String(p)).join('|') +
          ')')
    )
  }

  #fillNegs() {
    /* c8 ignore start */
    if (this !== this.#root) throw new Error('should only call on root')
    if (this.#filledNegs) return this
    /* c8 ignore stop */

    // call toString() once to fill this out
    this.toString()
    this.#filledNegs = true
    let n: AST | undefined
    while ((n = this.#negs.pop())) {
      if (n.type !== '!') continue
      // walk up the tree, appending everthing that comes AFTER parentIndex
      let p: AST | undefined = n
      let pp = p.#parent
      while (pp) {
        for (
          let i = p.#parentIndex + 1;
          !pp.type && i < pp.#parts.length;
          i++
        ) {
          for (const part of n.#parts) {
            /* c8 ignore start */
            if (typeof part === 'string') {
              throw new Error('string part in extglob AST??')
            }
            /* c8 ignore stop */
            part.copyIn(pp.#parts[i])
          }
        }
        p = pp
        pp = p.#parent
      }
    }
    return this
  }

  push(...parts: (string | AST)[]) {
    for (const p of parts) {
      if (p === '') continue
      /* c8 ignore start */
      if (
        typeof p !== 'string' &&
        !(p instanceof AST && p.#parent === this)
      ) {
        throw new Error('invalid part: ' + p)
      }
      /* c8 ignore stop */
      this.#parts.push(p)
    }
  }

  toJSON() {
    const ret: unknown[] =
      this.type === null ?
        this.#parts
          .slice()
          .map(p => (typeof p === 'string' ? p : p.toJSON()))
      : [this.type, ...this.#parts.map(p => (p as AST).toJSON())]
    if (this.isStart() && !this.type) ret.unshift([])
    if (
      this.isEnd() &&
      (this === this.#root ||
        (this.#root.#filledNegs && this.#parent?.type === '!'))
    ) {
      ret.push({})
    }
    return ret
  }

  isStart(): boolean {
    if (this.#root === this) return true
    // if (this.type) return !!this.#parent?.isStart()
    if (!this.#parent?.isStart()) return false
    if (this.#parentIndex === 0) return true
    // if everything AHEAD of this is a negation, then it's still the "start"
    const p = this.#parent
    for (let i = 0; i < this.#parentIndex; i++) {
      const pp = p.#parts[i]
      if (!(pp instanceof AST && pp.type === '!')) {
        return false
      }
    }
    return true
  }

  isEnd(): boolean {
    if (this.#root === this) return true
    if (this.#parent?.type === '!') return true
    if (!this.#parent?.isEnd()) return false
    if (!this.type) return this.#parent?.isEnd()
    // if not root, it'll always have a parent
    /* c8 ignore start */
    const pl = this.#parent ? this.#parent.#parts.length : 0
    /* c8 ignore stop */
    return this.#parentIndex === pl - 1
  }

  copyIn(part: AST | string) {
    if (typeof part === 'string') this.push(part)
    else this.push(part.clone(this))
  }

  clone(parent: AST) {
    const c = new AST(this.type, parent)
    for (const p of this.#parts) {
      c.copyIn(p)
    }
    return c
  }

  static #parseAST(
    str: string,
    ast: AST,
    pos: number,
    opt: MinimatchOptions,
    extDepth: number,
  ): number {
    const maxDepth = opt.maxExtglobRecursion ?? 2
    let escaping = false
    let inBrace = false
    let braceStart = -1
    let braceNeg = false
    if (ast.type === null) {
      // outside of a extglob, append until we find a start
      let i = pos
      let acc = ''
      while (i < str.length) {
        const c = str.charAt(i++)
        // still accumulate escapes at this point, but we do ignore
        // starts that are escaped
        if (escaping || c === '\\') {
          escaping = !escaping
          acc += c
          continue
        }

        if (inBrace) {
          if (i === braceStart + 1) {
            if (c === '^' || c === '!') {
              braceNeg = true
            }
          } else if (c === ']' && !(i === braceStart + 2 && braceNeg)) {
            inBrace = false
          }
          acc += c
          continue
        } else if (c === '[') {
          inBrace = true
          braceStart = i
          braceNeg = false
          acc += c
          continue
        }

        // we don't have to check for adoption here, because that's
        // done at the other recursion point.
        const doRecurse =
          !opt.noext &&
          isExtglobType(c) &&
          str.charAt(i) === '(' &&
          extDepth <= maxDepth
        if (doRecurse) {
          ast.push(acc)
          acc = ''
          const ext = new AST(c, ast)
          i = AST.#parseAST(str, ext, i, opt, extDepth + 1)
          ast.push(ext)
          continue
        }
        acc += c
      }
      ast.push(acc)
      return i
    }

    // some kind of extglob, pos is at the (
    // find the next | or )
    let i = pos + 1
    let part = new AST(null, ast)
    const parts: AST[] = []
    let acc = ''
    while (i < str.length) {
      const c = str.charAt(i++)
      // still accumulate escapes at this point, but we do ignore
      // starts that are escaped
      if (escaping || c === '\\') {
        escaping = !escaping
        acc += c
        continue
      }

      if (inBrace) {
        if (i === braceStart + 1) {
          if (c === '^' || c === '!') {
            braceNeg = true
          }
        } else if (c === ']' && !(i === braceStart + 2 && braceNeg)) {
          inBrace = false
        }
        acc += c
        continue
      } else if (c === '[') {
        inBrace = true
        braceStart = i
        braceNeg = false
        acc += c
        continue
      }

      const doRecurse =
        !opt.noext &&
        isExtglobType(c) &&
        str.charAt(i) === '(' &&
        /* c8 ignore start - the maxDepth is sufficient here */
        (extDepth <= maxDepth || (ast && ast.#canAdoptType(c)))
      /* c8 ignore stop */
      if (doRecurse) {
        const depthAdd = ast && ast.#canAdoptType(c) ? 0 : 1
        part.push(acc)
        acc = ''
        const ext = new AST(c, part)
        part.push(ext)
        i = AST.#parseAST(str, ext, i, opt, extDepth + depthAdd)
        continue
      }
      if (c === '|') {
        part.push(acc)
        acc = ''
        parts.push(part)
        part = new AST(null, ast)
        continue
      }
      if (c === ')') {
        if (acc === '' && ast.#parts.length === 0) {
          ast.#emptyExt = true
        }
        part.push(acc)
        acc = ''
        ast.push(...parts, part)
        return i
      }
      acc += c
    }

    // unfinished extglob
    // if we got here, it was a malformed extglob! not an extglob, but
    // maybe something else in there.
    ast.type = null
    ast.#hasMagic = undefined
    ast.#parts = [str.substring(pos - 1)]
    return i
  }

  #canAdoptWithSpace(child?: AST | string): child is AST & {
    type: null
    parts: [AST & { type: ExtglobType }]
  } {
    return this.#canAdopt(child, adoptionWithSpaceMap)
  }

  #canAdopt(
    child?: AST | string,
    map: Map<ExtglobType, ExtglobType[]> = adoptionMap,
  ): child is AST & {
    type: null
    parts: [AST & { type: ExtglobType }]
  } {
    if (
      !child ||
      typeof child !== 'object' ||
      child.type !== null ||
      child.#parts.length !== 1 ||
      this.type === null
    ) {
      return false
    }
    const gc = child.#parts[0]
    if (!gc || typeof gc !== 'object' || gc.type === null) {
      return false
    }
    return (this as AST & { type: ExtglobType }).#canAdoptType(
      gc.type,
      map,
    )
  }
  #canAdoptType(
    c: string,
    map: Map<ExtglobType, ExtglobType[]> = adoptionAnyMap,
  ): c is ExtglobType {
    return !!map.get(this.type as ExtglobType)?.includes(c as ExtglobType)
  }

  #adoptWithSpace(
    this: AST & { type: ExtglobType },
    child: AST & {
      type: null
    },
    index: number,
  ) {
    const gc = child.#parts[0] as AST & { type: ExtglobType }
    const blank = new AST(null, gc, this.options)
    blank.#parts.push('')
    gc.push(blank)
    this.#adopt(child, index)
  }

  #adopt(
    child: AST & {
      type: null
    },
    index: number,
  ) {
    const gc = child.#parts[0] as AST & { type: ExtglobType }
    this.#parts.splice(index, 1, ...gc.#parts)
    for (const p of gc.#parts) {
      if (typeof p === 'object') p.#parent = this
    }
    this.#toString = undefined
  }

  #canUsurpType(c: string): boolean {
    const m = usurpMap.get(this.type as ExtglobType)
    return !!m?.has(c as ExtglobType)
  }

  #canUsurp(child?: AST | string): child is AST & {
    type: null
    parts: [AST & { type: ExtglobType }]
  } {
    if (
      !child ||
      typeof child !== 'object' ||
      child.type !== null ||
      child.#parts.length !== 1 ||
      this.type === null ||
      this.#parts.length !== 1
    ) {
      return false
    }
    const gc = child.#parts[0]
    if (!gc || typeof gc !== 'object' || gc.type === null) {
      return false
    }
    return (this as AST & { type: ExtglobType }).#canUsurpType(gc.type)
  }

  #usurp(this: AST & { type: ExtglobType }, child: AST & { type: null }) {
    const m = usurpMap.get(this.type as ExtglobType)
    const gc = child.#parts[0] as AST & { type: ExtglobType }
    const nt = m?.get(gc.type)
    /* c8 ignore start - impossible */
    if (!nt) return false
    /* c8 ignore stop */
    this.#parts = gc.#parts
    for (const p of this.#parts) {
      if (typeof p === 'object') {
        p.#parent = this
      }
    }
    this.type = nt
    this.#toString = undefined
    this.#emptyExt = false
  }

  static fromGlob(pattern: string, options: MinimatchOptions = {}) {
    const ast = new AST(null, undefined, options)
    AST.#parseAST(pattern, ast, 0, options, 0)
    return ast
  }

  // returns the regular expression if there's magic, or the unescaped
  // string if not.
  toMMPattern(): MMRegExp | string {
    // should only be called on root
    /* c8 ignore start */
    if (this !== this.#root) return this.#root.toMMPattern()
    /* c8 ignore stop */
    const glob = this.toString()
    const [re, body, hasMagic, uflag] = this.toRegExpSource()
    // if we're in nocase mode, and not nocaseMagicOnly, then we do
    // still need a regular expression if we have to case-insensitively
    // match capital/lowercase characters.
    const anyMagic =
      hasMagic ||
      this.#hasMagic ||
      (this.#options.nocase &&
        !this.#options.nocaseMagicOnly &&
        glob.toUpperCase() !== glob.toLowerCase())
    if (!anyMagic) {
      return body
    }

    const flags = (this.#options.nocase ? 'i' : '') + (uflag ? 'u' : '')
    return Object.assign(new RegExp(`^${re}$`, flags), {
      _src: re,
      _glob: glob,
    })
  }

  get options() {
    return this.#options
  }

  // returns the string match, the regexp source, whether there's magic
  // in the regexp (so a regular expression is required) and whether or
  // not the uflag is needed for the regular expression (for posix classes)
  // TODO: instead of injecting the start/end at this point, just return
  // the BODY of the regexp, along with the start/end portions suitable
  // for binding the start/end in either a joined full-path makeRe context
  // (where we bind to (^|/), or a standalone matchPart context (where
  // we bind to ^, and not /).  Otherwise slashes get duped!
  //
  // In part-matching mode, the start is:
  // - if not isStart: nothing
  // - if traversal possible, but not allowed: ^(?!\.\.?$)
  // - if dots allowed or not possible: ^
  // - if dots possible and not allowed: ^(?!\.)
  // end is:
  // - if not isEnd(): nothing
  // - else: $
  //
  // In full-path matching mode, we put the slash at the START of the
  // pattern, so start is:
  // - if first pattern: same as part-matching mode
  // - if not isStart(): nothing
  // - if traversal possible, but not allowed: /(?!\.\.?(?:$|/))
  // - if dots allowed or not possible: /
  // - if dots possible and not allowed: /(?!\.)
  // end is:
  // - if last pattern, same as part-matching mode
  // - else nothing
  //
  // Always put the (?:$|/) on negated tails, though, because that has to be
  // there to bind the end of the negated pattern portion, and it's easier to
  // just stick it in now rather than try to inject it later in the middle of
  // the pattern.
  //
  // We can just always return the same end, and leave it up to the caller
  // to know whether it's going to be used joined or in parts.
  // And, if the start is adjusted slightly, can do the same there:
  // - if not isStart: nothing
  // - if traversal possible, but not allowed: (?:/|^)(?!\.\.?$)
  // - if dots allowed or not possible: (?:/|^)
  // - if dots possible and not allowed: (?:/|^)(?!\.)
  //
  // But it's better to have a simpler binding without a conditional, for
  // performance, so probably better to return both start options.
  //
  // Then the caller just ignores the end if it's not the first pattern,
  // and the start always gets applied.
  //
  // But that's always going to be $ if it's the ending pattern, or nothing,
  // so the caller can just attach $ at the end of the pattern when building.
  //
  // So the todo is:
  // - better detect what kind of start is needed
  // - return both flavors of starting pattern
  // - attach $ at the end of the pattern when creating the actual RegExp
  //
  // Ah, but wait, no, that all only applies to the root when the first pattern
  // is not an extglob. If the first pattern IS an extglob, then we need all
  // that dot prevention biz to live in the extglob portions, because eg
  // +(*|.x*) can match .xy but not .yx.
  //
  // So, return the two flavors if it's #root and the first child is not an
  // AST, otherwise leave it to the child AST to handle it, and there,
  // use the (?:^|/) style of start binding.
  //
  // Even simplified further:
  // - Since the start for a join is eg /(?!\.) and the start for a part
  // is ^(?!\.), we can just prepend (?!\.) to the pattern (either root
  // or start or whatever) and prepend ^ or / at the Regexp construction.
  toRegExpSource(
    allowDot?: boolean,
  ): [re: string, body: string, hasMagic: boolean, uflag: boolean] {
    const dot = allowDot ?? !!this.#options.dot
    if (this.#root === this) {
      this.#flatten()
      this.#fillNegs()
    }
    if (!isExtglobAST(this)) {
      const noEmpty =
        this.isStart() &&
        this.isEnd() &&
        !this.#parts.some(s => typeof s !== 'string')
      const src = this.#parts
        .map(p => {
          const [re, _, hasMagic, uflag] =
            typeof p === 'string' ?
              AST.#parseGlob(p, this.#hasMagic, noEmpty)
            : p.toRegExpSource(allowDot)
          this.#hasMagic = this.#hasMagic || hasMagic
          this.#uflag = this.#uflag || uflag
          return re
        })
        .join('')

      let start = ''
      if (this.isStart()) {
        if (typeof this.#parts[0] === 'string') {
          // this is the string that will match the start of the pattern,
          // so we need to protect against dots and such.

          // '.' and '..' cannot match unless the pattern is that exactly,
          // even if it starts with . or dot:true is set.
          const dotTravAllowed =
            this.#parts.length === 1 && justDots.has(this.#parts[0])
          if (!dotTravAllowed) {
            const aps = addPatternStart
            // check if we have a possibility of matching . or ..,
            // and prevent that.
            const needNoTrav =
              // dots are allowed, and the pattern starts with [ or .
              (dot && aps.has(src.charAt(0))) ||
              // the pattern starts with \., and then [ or .
              (src.startsWith('\\.') && aps.has(src.charAt(2))) ||
              // the pattern starts with \.\., and then [ or .
              (src.startsWith('\\.\\.') && aps.has(src.charAt(4)))
            // no need to prevent dots if it can't match a dot, or if a
            // sub-pattern will be preventing it anyway.
            const needNoDot = !dot && !allowDot && aps.has(src.charAt(0))

            start =
              needNoTrav ? startNoTraversal
              : needNoDot ? startNoDot
              : ''
          }
        }
      }

      // append the "end of path portion" pattern to negation tails
      let end = ''
      if (
        this.isEnd() &&
        this.#root.#filledNegs &&
        this.#parent?.type === '!'
      ) {
        end = '(?:$|\\/)'
      }
      const final = start + src + end
      return [
        final,
        unescape(src),
        (this.#hasMagic = !!this.#hasMagic),
        this.#uflag,
      ]
    }

    // We need to calculate the body *twice* if it's a repeat pattern
    // at the start, once in nodot mode, then again in dot mode, so a
    // pattern like *(?) can match 'x.y'

    const repeated = this.type === '*' || this.type === '+'
    // some kind of extglob
    const start = this.type === '!' ? '(?:(?!(?:' : '(?:'
    let body = (this as AST & { type: ExtglobType }).#partsToRegExp(dot)

    if (this.isStart() && this.isEnd() && !body && this.type !== '!') {
      // invalid extglob, has to at least be *something* present, if it's
      // the entire path portion.
      const s = this.toString()
      const me = this as AST
      me.#parts = [s]
      me.type = null
      me.#hasMagic = undefined
      return [s, unescape(this.toString()), false, false]
    }

    let bodyDotAllowed =
      !repeated || allowDot || dot || !startNoDot ?
        ''
      : this.#partsToRegExp(true)
    if (bodyDotAllowed === body) {
      bodyDotAllowed = ''
    }
    if (bodyDotAllowed) {
      body = `(?:${body})(?:${bodyDotAllowed})*?`
    }

    // an empty !() is exactly equivalent to a starNoEmpty
    let final = ''
    if (this.type === '!' && this.#emptyExt) {
      final = (this.isStart() && !dot ? startNoDot : '') + starNoEmpty
    } else {
      const close =
        this.type === '!' ?
          // !() must match something,but !(x) can match ''
          '))' +
          (this.isStart() && !dot && !allowDot ? startNoDot : '') +
          star +
          ')'
        : this.type === '@' ? ')'
        : this.type === '?' ? ')?'
        : this.type === '+' && bodyDotAllowed ? ')'
        : this.type === '*' && bodyDotAllowed ? `)?`
        : `)${this.type}`
      final = start + body + close
    }
    return [
      final,
      unescape(body),
      (this.#hasMagic = !!this.#hasMagic),
      this.#uflag,
    ]
  }

  #flatten() {
    if (!isExtglobAST(this)) {
      for (const p of this.#parts) {
        if (typeof p === 'object') {
          p.#flatten()
        }
      }
    } else {
      // do up to 10 passes to flatten as much as possible
      let iterations = 0
      let done = false
      do {
        done = true
        for (let i = 0; i < this.#parts.length; i++) {
          const c = this.#parts[i]
          if (typeof c === 'object') {
            c.#flatten()
            if (this.#canAdopt(c)) {
              done = false
              this.#adopt(c, i)
            } else if (this.#canAdoptWithSpace(c)) {
              done = false
              ;(this as AST & { type: ExtglobType }).#adoptWithSpace(c, i)
            } else if (this.#canUsurp(c)) {
              done = false
              ;(this as AST & { type: ExtglobType }).#usurp(c)
            }
          }
        }
      } while (!done && ++iterations < 10)
    }
    this.#toString = undefined
  }

  #partsToRegExp(this: AST & { type: ExtglobType }, dot: boolean) {
    return this.#parts
      .map(p => {
        // extglob ASTs should only contain parent ASTs
        /* c8 ignore start */
        if (typeof p === 'string') {
          throw new Error('string type in extglob ast??')
        }
        /* c8 ignore stop */
        // can ignore hasMagic, because extglobs are already always magic
        const [re, _, _hasMagic, uflag] = p.toRegExpSource(dot)
        this.#uflag = this.#uflag || uflag
        return re
      })
      .filter(p => !(this.isStart() && this.isEnd()) || !!p)
      .join('|')
  }

  static #parseGlob(
    glob: string,
    hasMagic: boolean | undefined,
    noEmpty: boolean = false,
  ): [re: string, body: string, hasMagic: boolean, uflag: boolean] {
    let escaping = false
    let re = ''
    let uflag = false
    // multiple stars that aren't globstars coalesce into one *
    let inStar = false
    for (let i = 0; i < glob.length; i++) {
      const c = glob.charAt(i)
      if (escaping) {
        escaping = false
        re += (reSpecials.has(c) ? '\\' : '') + c
        continue
      }
      if (c === '*') {
        if (inStar) continue
        inStar = true
        re += noEmpty && /^[*]+$/.test(glob) ? starNoEmpty : star
        hasMagic = true
        continue
      } else {
        inStar = false
      }
      if (c === '\\') {
        if (i === glob.length - 1) {
          re += '\\\\'
        } else {
          escaping = true
        }
        continue
      }
      if (c === '[') {
        const [src, needUflag, consumed, magic] = parseClass(glob, i)
        if (consumed) {
          re += src
          uflag = uflag || needUflag
          i += consumed - 1
          hasMagic = hasMagic || magic
          continue
        }
      }
      if (c === '?') {
        re += qmark
        hasMagic = true
        continue
      }
      re += regExpEscape(c)
    }
    return [re, unescape(glob), !!hasMagic, uflag]
  }
}

// translate the various posix character classes into unicode properties
// this works across all unicode locales

// { <posix class>: [<translation>, /u flag required, negated]
const posixClasses: { [k: string]: [e: string, u: boolean, n?: boolean] } =
  {
    '[:alnum:]': ['\\p{L}\\p{Nl}\\p{Nd}', true],
    '[:alpha:]': ['\\p{L}\\p{Nl}', true],
    '[:ascii:]': ['\\x' + '00-\\x' + '7f', false],
    '[:blank:]': ['\\p{Zs}\\t', true],
    '[:cntrl:]': ['\\p{Cc}', true],
    '[:digit:]': ['\\p{Nd}', true],
    '[:graph:]': ['\\p{Z}\\p{C}', true, true],
    '[:lower:]': ['\\p{Ll}', true],
    '[:print:]': ['\\p{C}', true],
    '[:punct:]': ['\\p{P}', true],
    '[:space:]': ['\\p{Z}\\t\\r\\n\\v\\f', true],
    '[:upper:]': ['\\p{Lu}', true],
    '[:word:]': ['\\p{L}\\p{Nl}\\p{Nd}\\p{Pc}', true],
    '[:xdigit:]': ['A-Fa-f0-9', false],
  }

// only need to escape a few things inside of brace expressions
// escapes: [ \ ] -
const braceEscape = (s: string) => s.replace(/[[\]\\-]/g, '\\$&')
// escape all regexp magic characters
const regexpEscape = (s: string) =>
  s.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&')

// everything has already been escaped, we just have to join
const rangesToString = (ranges: string[]): string => ranges.join('')

export type ParseClassResult = [
  src: string,
  uFlag: boolean,
  consumed: number,
  hasMagic: boolean,
]

// takes a glob string at a posix brace expression, and returns
// an equivalent regular expression source, and boolean indicating
// whether the /u flag needs to be applied, and the number of chars
// consumed to parse the character class.
// This also removes out of order ranges, and returns ($.) if the
// entire class just no good.
export const parseClass = (
  glob: string,
  position: number,
): ParseClassResult => {
  const pos = position
  /* c8 ignore start */
  if (glob.charAt(pos) !== '[') {
    throw new Error('not in a brace expression')
  }
  /* c8 ignore stop */
  const ranges: string[] = []
  const negs: string[] = []

  let i = pos + 1
  let sawStart = false
  let uflag = false
  let escaping = false
  let negate = false
  let endPos = pos
  let rangeStart = ''
  WHILE: while (i < glob.length) {
    const c = glob.charAt(i)
    if ((c === '!' || c === '^') && i === pos + 1) {
      negate = true
      i++
      continue
    }

    if (c === ']' && sawStart && !escaping) {
      endPos = i + 1
      break
    }

    sawStart = true
    if (c === '\\') {
      if (!escaping) {
        escaping = true
        i++
        continue
      }
      // escaped \ char, fall through and treat like normal char
    }
    if (c === '[' && !escaping) {
      // either a posix class, a collation equivalent, or just a [
      for (const [cls, [unip, u, neg]] of Object.entries(posixClasses)) {
        if (glob.startsWith(cls, i)) {
          // invalid, [a-[] is fine, but not [a-[:alpha]]
          if (rangeStart) {
            return ['$.', false, glob.length - pos, true]
          }
          i += cls.length
          if (neg) negs.push(unip)
          else ranges.push(unip)
          uflag = uflag || u
          continue WHILE
        }
      }
    }

    // now it's just a normal character, effectively
    escaping = false
    if (rangeStart) {
      // throw this range away if it's not valid, but others
      // can still match.
      if (c > rangeStart) {
        ranges.push(braceEscape(rangeStart) + '-' + braceEscape(c))
      } else if (c === rangeStart) {
        ranges.push(braceEscape(c))
      }
      rangeStart = ''
      i++
      continue
    }

    // now might be the start of a range.
    // can be either c-d or c-] or c<more...>] or c] at this point
    if (glob.startsWith('-]', i + 1)) {
      ranges.push(braceEscape(c + '-'))
      i += 2
      continue
    }
    if (glob.startsWith('-', i + 1)) {
      rangeStart = c
      i += 2
      continue
    }

    // not the start of a range, just a single character
    ranges.push(braceEscape(c))
    i++
  }

  if (endPos < i) {
    // didn't see the end of the class, not a valid class,
    // but might still be valid as a literal match.
    return ['', false, 0, false]
  }

  // if we got no ranges and no negates, then we have a range that
  // cannot possibly match anything, and that poisons the whole glob
  if (!ranges.length && !negs.length) {
    return ['$.', false, glob.length - pos, true]
  }

  // if we got one positive range, and it's a single character, then that's
  // not actually a magic pattern, it's just that one literal character.
  // we should not treat that as "magic", we should just return the literal
  // character. [_] is a perfectly valid way to escape glob magic chars.
  if (
    negs.length === 0 &&
    ranges.length === 1 &&
    /^\\?.$/.test(ranges[0]) &&
    !negate
  ) {
    const r = ranges[0].length === 2 ? ranges[0].slice(-1) : ranges[0]
    return [regexpEscape(r), false, endPos - pos, false]
  }

  const sranges = '[' + (negate ? '^' : '') + rangesToString(ranges) + ']'
  const snegs = '[' + (negate ? '' : '^') + rangesToString(negs) + ']'
  const comb =
    ranges.length && negs.length ? '(' + sranges + '|' + snegs + ')'
    : ranges.length ? sranges
    : snegs

  return [comb, uflag, endPos - pos, true]
}

import type { MinimatchOptions } from './index.js'

/**
 * Escape all magic characters in a glob pattern.
 *
 * If the {@link MinimatchOptions.windowsPathsNoEscape}
 * option is used, then characters are escaped by wrapping in `[]`, because
 * a magic character wrapped in a character class can only be satisfied by
 * that exact character.  In this mode, `\` is _not_ escaped, because it is
 * not interpreted as a magic character, but instead as a path separator.
 *
 * If the {@link MinimatchOptions.magicalBraces} option is used,
 * then braces (`{` and `}`) will be escaped.
 */
export const escape = (
  s: string,
  {
    windowsPathsNoEscape = false,
    magicalBraces = false,
  }: Pick<MinimatchOptions, 'windowsPathsNoEscape' | 'magicalBraces'> = {},
) => {
  // don't need to escape +@! because we escape the parens
  // that make those magic, and escaping ! as [!] isn't valid,
  // because [!]] is a valid glob class meaning not ']'.
  if (magicalBraces) {
    return windowsPathsNoEscape ?
        s.replace(/[?*()[\]{}]/g, '[$&]')
      : s.replace(/[?*()[\]\\{}]/g, '\\$&')
  }
  return windowsPathsNoEscape ?
      s.replace(/[?*()[\]]/g, '[$&]')
    : s.replace(/[?*()[\]\\]/g, '\\$&')
}

export * from './construct';
export type * from './metadata';
export type * from './mixin';
export * from './dependency';

import type { IDependable } from './dependency';
import { Dependable } from './dependency';
import type { MetadataEntry } from './metadata';
import type { IMixin } from './mixin';
import { captureStackTrace } from './private/stack-trace';
import { addressOf } from './private/uniqueid';

const CONSTRUCT_SYM = Symbol.for('constructs.Construct');

/**
 * Represents a construct.
 */
export interface IConstruct extends IDependable {
  /**
   * The tree node.
   */
  readonly node: Node;

  /**
   * Applies one or more mixins to this construct.
   *
   * Mixins are applied in order. The list of constructs is captured at the
   * start of the call, so constructs added by a mixin will not be visited.
   *
   * @param mixins The mixins to apply
   * @returns This construct for chaining
   */
  with(...mixins: IMixin[]): IConstruct;
}

/**
 * Represents the construct node in the scope tree.
 */
export class Node {
  /**
   * Separator used to delimit construct path components.
   */
  public static readonly PATH_SEP = '/';

  /**
   * Returns the node associated with a construct.
   * @param construct the construct
   *
   * @deprecated use `construct.node` instead
   */
  public static of(construct: IConstruct): Node {
    return construct.node;
  }

  /**
   * Returns the scope in which this construct is defined.
   *
   * The value is `undefined` at the root of the construct scope tree.
   */
  public readonly scope?: IConstruct;

  /**
   * The id of this construct within the current scope.
   *
   * This is a scope-unique id. To obtain an app-unique id for this construct, use `addr`.
   */
  public readonly id: string;

  /**
   * The full, absolute path of this construct in the tree.
   *
   * Components are separated by '/'.
   */
  public readonly path: string;

  private _locked = false; // if this is "true", addChild will fail
  private _children: { [id: string]: IConstruct } | undefined;
  private _context: { [key: string]: any } | undefined;
  private _metadata: Array<MetadataEntry> | undefined;
  private _dependencies: Set<IDependable> | undefined;
  private _defaultChild: IConstruct | undefined;
  private _validations: Array<IValidation> | undefined;
  private _addr?: string; // cache
  private _scopes: readonly IConstruct[];


  public constructor(private readonly host: Construct, scope: IConstruct, id: string) {
    id = id ?? ''; // if undefined, convert to empty string

    this.id = sanitizeId(id);
    this.scope = scope;

    if (scope && !this.id) {
      throw new Error('Only root constructs may have an empty ID');
    }

    if (scope) {
      scope.node.addChild(host, this.id);
      this.path = scope.node.path ? `${scope.node.path}${Node.PATH_SEP}${this.id}` : this.id;
      this._scopes = [...scope.node._scopes, this.host];
    } else {
      this.path = this.id;
      this._scopes = [this.host];
    }
  }

  /**
   * All parent scopes of this construct.
   *
   * @returns a list of parent scopes. The last element in the list will always
   * be the current construct and the first element will be the root of the
   * tree.
   */
  public get scopes(): IConstruct[] {
    // Needs to return a copy to make sure callers can't accidentally mutate
    // internal state. jsii doesn't support ReadonlyArray.
    return [...this._scopes];
  }

  /**
   * Returns an opaque tree-unique address for this construct.
   *
   * Addresses are 42 characters hexadecimal strings. They begin with "c8"
   * followed by 40 lowercase hexadecimal characters (0-9a-f).
   *
   * Addresses are calculated using a SHA-1 of the components of the construct
   * path.
   *
   * To enable refactoring of construct trees, constructs with the ID `Default`
   * will be excluded from the calculation. In those cases constructs in the
   * same tree may have the same address.
   *
   * @example c83a2846e506bcc5f10682b564084bca2d275709ee
   */
  public get addr(): string {
    if (!this._addr) {
      this._addr = addressOf(this._scopes.map(c => c.node.id));
    }

    return this._addr;
  }

  /**
   * Return a direct child by id, or undefined
   *
   * @param id Identifier of direct child
   * @returns the child if found, or undefined
   */
  public tryFindChild(id: string): IConstruct | undefined {
    return this._children?.[sanitizeId(id)];
  }

  /**
   * Return a direct child by id
   *
   * Throws an error if the child is not found.
   *
   * @param id Identifier of direct child
   * @returns Child with the given id.
   */
  public findChild(id: string): IConstruct {
    const ret = this.tryFindChild(id);
    if (!ret) {
      throw new Error(`No child with id: '${id}'`);
    }
    return ret;
  }

  /**
   * Returns the child construct that has the id `Default` or `Resource`.
   * This is usually the construct that provides the bulk of the underlying functionality.
   * Useful for modifications of the underlying construct that are not available at the higher levels.
   *
   * @throws if there is more than one child
   * @returns a construct or undefined if there is no default child
   */
  public get defaultChild(): IConstruct | undefined {
    if (this._defaultChild !== undefined) {
      return this._defaultChild;
    }

    const resourceChild = this.tryFindChild('Resource');
    const defaultChild = this.tryFindChild('Default');
    if (resourceChild && defaultChild) {
      throw new Error(`Cannot determine default child for ${this.path}. There is both a child with id "Resource" and id "Default"`);
    }

    return defaultChild || resourceChild;
  }

  /**
   * Override the defaultChild property.
   *
   * This should only be used in the cases where the correct
   * default child is not named 'Resource' or 'Default' as it
   * should be.
   *
   * If you set this to undefined, the default behavior of finding
   * the child named 'Resource' or 'Default' will be used.
   */
  public set defaultChild(value: IConstruct | undefined) {
    this._defaultChild = value;
  }

  /**
   * All direct children of this construct.
   */
  public get children() {
    return Object.values(this._children ?? {});
  }

  /**
   * Return this construct and all of its children in the given order
   */
  public findAll(order: ConstructOrder = ConstructOrder.PREORDER): IConstruct[] {
    const ret = new Array<IConstruct>();
    visit(this.host);
    return ret;

    function visit(c: IConstruct) {
      if (order === ConstructOrder.PREORDER) {
        ret.push(c);
      }

      for (const child of c.node.children) {
        visit(child);
      }

      if (order === ConstructOrder.POSTORDER) {
        ret.push(c);
      }
    }
  }

  /**
   * This can be used to set contextual values.
   * Context must be set before any children are added, since children may consult context info during construction.
   * If the key already exists, it will be overridden.
   * @param key The context key
   * @param value The context value
   */
  public setContext(key: string, value: any) {
    if (this.children.length > 0) {
      const names = this.children.map(c => c.node.id);
      throw new Error('Cannot set context after children have been added: ' + names.join(','));
    }
    if (!this._context) {
      this._context = {};
    }
    this._context[key] = value;
  }

  /**
   * Retrieves a value from tree context if present. Otherwise, would throw an error.
   *
   * Context is usually initialized at the root, but can be overridden at any point in the tree.
   *
   * @param key The context key
   * @returns The context value or throws error if there is no context value for this key
   */
  public getContext(key: string): any {
    const value = this._context?.[key];

    if (value !== undefined) { return value; }

    if (value === undefined && !this.scope?.node) {
      throw new Error(`No context value present for ${key} key`);
    }

    return this.scope && this.scope.node.getContext(key);
  }

  /**
   * Retrieves the all context of a node from tree context.
   *
   * Context is usually initialized at the root, but can be overridden at any point in the tree.
   *
   * @param defaults Any keys to override the retrieved context
   * @returns The context object or an empty object if there is discovered context
   */
  public getAllContext(defaults?: object): any {
    const ret = { ...defaults };
    for (const scope of this._scopes) {
      Object.assign(ret, scope.node._context);
    }
    return ret;
  }

  /**
   * Retrieves a value from tree context.
   *
   * Context is usually initialized at the root, but can be overridden at any point in the tree.
   *
   * @param key The context key
   * @returns The context value or `undefined` if there is no context value for this key.
   */
  public tryGetContext(key: string): any {
    const value = this._context?.[key];
    if (value !== undefined) { return value; }

    return this.scope && this.scope.node.tryGetContext(key);
  }

  /**
   * An immutable array of metadata objects associated with this construct.
   * This can be used, for example, to implement support for deprecation notices, source mapping, etc.
   */
  public get metadata() {
    return [...this._metadata ?? []];
  }

  /**
   * Adds a metadata entry to this construct.
   * Entries are arbitrary values and will also include a stack trace to allow tracing back to
   * the code location for when the entry was added. It can be used, for example, to include source
   * mapping in CloudFormation templates to improve diagnostics.
   * Note that construct metadata is not the same as CloudFormation resource metadata and is never written to the CloudFormation template.
   * The metadata entries are written to the Cloud Assembly Manifest if the `treeMetadata` property is specified in the props of the App that contains this Construct.
   *
   * @param type a string denoting the type of metadata
   * @param data the value of the metadata (can be a Token). If null/undefined, metadata will not be added.
   * @param options options
   */
  public addMetadata(type: string, data: any, options: MetadataOptions = { }): void {
    if (data == null) {
      return;
    }

    const node = this;
    function getTrace() {
      if (options.stackTraceOverride && options.stackTraceOverride.length > 0) {
        return options.stackTraceOverride;
      }
      const shouldTrace = options.stackTrace ?? false;
      return shouldTrace ? captureStackTrace(options.traceFromFunction ?? node.addMetadata) : undefined;
    }

    if (!this._metadata) {
      this._metadata = [];
    }
    this._metadata.push({ type, data, trace: getTrace() });
  }

  /**
   * Returns the root of the construct tree.
   * @returns The root of the construct tree.
   */
  public get root() {
    return this._scopes[0];
  }

  /**
   * Returns true if this construct or the scopes in which it is defined are
   * locked.
   */
  public get locked() {
    if (this._locked) {
      return true;
    }

    if (this.scope && this.scope.node.locked) {
      return true;
    }

    return false;
  }

  /**
   * Add an ordering dependency on a Dependable (a construct or set of constructs)
   *
   * It is up to the target document language to decide what an ordering
   * relationship means and how it should be rendered; for example, in the AWS
   * CDK for CloudFormation it means a dependency from every resource in scope
   * of the current construct to every resource in scope of the target set
   * of constructs, that get realized as either stack dependencies or
   * `DependsOn` relationships in the synthesized template.
   *
   * `IDependable` is a marker interface that indicates that a class has used
   * `Dependable.implement()` to implement the `IDependable` interface. It
   * can be used to make the target object represent more than one set of
   * constructs at a time. For example, a `DependencyGroup` uses this
   * interface to represent an explicit list of 0 or more constructs that should
   * be involved in the dependency relationship.
   */
  public addDependency(...deps: IDependable[]) {
    if (!this._dependencies) {
      this._dependencies = new Set();
    }
    for (const d of deps) {
      this._dependencies.add(d);
    }
  }

  /**
   * Remove an ordering dependency on a Dependenable (a construct or set of constructs)
   *
   * This removes any dependency added using `node.addDependency()`. It must
   * use the exact same object that was involved in the `addDependency()` call.
   */
  public removeDependency(...deps: IDependable[]) {
    if (!this._dependencies) {
      this._dependencies = new Set();
    }
    for (const d of deps) {
      this._dependencies.delete(d);
    }
  }

  /**
   * Constructs that this construct depends on directly
   *
   * This expands the sets of `Dependables` to the set of `Constructs` that they
   * represent.
   */
  public get dependencies(): IConstruct[] {
    const result = new Array<IConstruct>();
    if (this._dependencies) {
      for (const dep of this._dependencies) {
        for (const root of Dependable.of(dep).dependencyRoots) {
          result.push(root);
        }
      }
    }
    return result;
  }

  /**
   * Remove the child with the given name, if present.
   *
   * @returns Whether a child with the given name was deleted.
   */
  public tryRemoveChild(childName: string): boolean {
    if (!this._children || !(childName in this._children)) { return false; }
    delete this._children[childName];
    return true;
  }

  /**
   * Adds a validation to this construct.
   *
   * When `node.validate()` is called, the `validate()` method will be called on
   * all validations and all errors will be returned.
   *
   * @param validation The validation object
   */
  public addValidation(validation: IValidation) {
    if (!this._validations) {
      this._validations = [];
    }
    this._validations.push(validation);
  }

  /**
   * Validates this construct.
   *
   * Invokes the `validate()` method on all validations added through
   * `addValidation()`.
   *
   * @returns an array of validation error messages associated with this
   * construct.
   */
  public validate(): string[] {
    return (this._validations ?? []).flatMap(v => v.validate());
  }

  /**
   * Locks this construct from allowing more children to be added. After this
   * call, no more children can be added to this construct or to any children.
   */
  public lock() {
    this._locked = true;
  }

  /**
   * Applies one or more mixins to this construct.
   *
   * Mixins are applied in order. The list of constructs is captured at the
   * start of the call, so constructs added by a mixin will not be visited.
   * Use multiple `with()` calls if subsequent mixins should apply to added
   * constructs.
   *
   * @param mixins The mixins to apply
   * @returns This construct for chaining
   */
  public with(...mixins: IMixin[]): IConstruct {
    const allConstructs = this.findAll();
    for (const mixin of mixins) {
      for (const construct of allConstructs) {
        if (mixin.supports(construct)) {
          mixin.applyTo(construct);
        }
      }
    }
    return this.host;
  };

  /**
   * Adds a child construct to this node.
   *
   * @param child The child construct
   * @param childName The type name of the child construct.
   * @returns The resolved path part name of the child
   */
  private addChild(child: Construct, childName: string) {
    if (this.locked) {

      // special error if root is locked
      if (!this.path) {
        throw new Error('Cannot add children during synthesis');
      }

      throw new Error(`Cannot add children to "${this.path}" during synthesis`);
    }

    if (!this._children) {
      this._children = {};
    }

    if (this._children[childName]) {
      const name = this.id ?? '';
      const typeName = this.host.constructor.name;
      throw new Error(`There is already a Construct with name '${childName}' in ${typeName}${name.length > 0 ? ' [' + name + ']' : ''}`);
    }

    this._children[childName] = child;
  }
}

/**
 * Represents the building block of the construct graph.
 *
 * All constructs besides the root construct must be created within the scope of
 * another construct.
 */
export class Construct implements IConstruct {
  /**
   * Checks if `x` is a construct.
   *
   * Use this method instead of `instanceof` to properly detect `Construct`
   * instances, even when the construct library is symlinked.
   *
   * Explanation: in JavaScript, multiple copies of the `constructs` library on
   * disk are seen as independent, completely different libraries. As a
   * consequence, the class `Construct` in each copy of the `constructs` library
   * is seen as a different class, and an instance of one class will not test as
   * `instanceof` the other class. `npm install` will not create installations
   * like this, but users may manually symlink construct libraries together or
   * use a monorepo tool: in those cases, multiple copies of the `constructs`
   * library can be accidentally installed, and `instanceof` will behave
   * unpredictably. It is safest to avoid using `instanceof`, and using
   * this type-testing method instead.
   *
   * @returns true if `x` is an object created from a class which extends `Construct`.
   * @param x Any object
   */
  public static isConstruct(x: any): x is Construct {
    return x && typeof x === 'object' && x[CONSTRUCT_SYM];
  }

  /**
   * The tree node.
   */
  public readonly node: Node;

  /**
   * Creates a new construct node.
   *
   * @param scope The scope in which to define this construct
   * @param id The scoped construct ID. Must be unique amongst siblings. If
   * the ID includes a path separator (`/`), then it will be replaced by double
   * dash `--`.
   */
  constructor(scope: Construct, id: string) {
    this.node = new Node(this, scope, id);

    // implement IDependable privately
    Dependable.implement(this, {
      dependencyRoots: [this],
    });
  }

  /**
   * Applies one or more mixins to this construct.
   *
   * Mixins are applied in order. The list of constructs is captured at the
   * start of the call, so constructs added by a mixin will not be visited.
   * Use multiple `with()` calls if subsequent mixins should apply to added
   * constructs.
   *
   * @param mixins The mixins to apply
   * @returns This construct for chaining
   */
  public with(...mixins: IMixin[]): IConstruct {
    return this.node.with(...mixins);
  };

  /**
   * Returns a string representation of this construct.
   */
  public toString() {
    return this.node.path || '<root>';
  }
}

/**
 * Implement this interface in order for the construct to be able to validate itself.
 */
export interface IValidation {
  /**
   * Validate the current construct.
   *
   * This method can be implemented by derived constructs in order to perform
   * validation logic. It is called on all constructs before synthesis.
   *
   * @returns An array of validation error messages, or an empty array if there the construct is valid.
   */
  validate(): string[];
}

/**
 * In what order to return constructs
 */
export enum ConstructOrder {
  /**
   * Depth-first, pre-order
   */
  PREORDER,

  /**
   * Depth-first, post-order (leaf nodes first)
   */
  POSTORDER,
}

const PATH_SEP_REGEX = new RegExp(`${Node.PATH_SEP}`, 'g');

/**
 * Return a sanitized version of an arbitrary string, so it can be used as an ID
 */
function sanitizeId(id: string) {
  // Escape path seps as double dashes
  return id.replace(PATH_SEP_REGEX, '--');
}

/**
 * Options for `construct.addMetadata()`.
 */
export interface MetadataOptions {
  /**
   * Include stack trace with metadata entry.
   * @default false
   */
  readonly stackTrace?: boolean;

  /**
   * A JavaScript function to begin tracing from.
   *
   * This option is ignored unless `stackTrace` is `true`.
   *
   * @default addMetadata()
   */
  readonly traceFromFunction?: any;

  /**
   * The actual stack trace to be added to the metadata. If this
   * parameter is passed, the stackTrace parameter is ignored.
   */
  readonly stackTraceOverride?: string[];
}

// Mark all instances of 'Construct'
Object.defineProperty(Construct.prototype, CONSTRUCT_SYM, {
  value: true,
  enumerable: false,
  writable: false,
});

/**
 * Creates a new root construct node.
 *
 * The root construct represents the top of the construct tree and is not contained within a parent scope itself.
 * For root constructs, the id is optional.
 */
export class RootConstruct extends Construct {
  /**
   * Creates a new root construct node.
   *
   * @param id The scoped construct ID. Must be unique amongst siblings. If
   * the ID includes a path separator (`/`), then it will be replaced by double
   * dash `--`.
   */
  constructor(id?: string) {
    super(undefined as any, id ?? '');
  }
}

import type { IConstruct } from './construct';

/**
 * Trait marker for classes that can be depended upon
 *
 * The presence of this interface indicates that an object has
 * an `IDependable` implementation.
 *
 * This interface can be used to take an (ordering) dependency on a set of
 * constructs. An ordering dependency implies that the resources represented by
 * those constructs are deployed before the resources depending ON them are
 * deployed.
 */
export interface IDependable {
  // Empty, this interface is a trait marker
}

/**
 * A set of constructs to be used as a dependable
 *
 * This class can be used when a set of constructs which are disjoint in the
 * construct tree needs to be combined to be used as a single dependable.
 */
export class DependencyGroup implements IDependable {
  private readonly _deps = new Array<IDependable>();

  constructor(...deps: IDependable[]) {
    const self = this;

    Dependable.implement(this, {
      get dependencyRoots() {
        const result = new Array<IConstruct>();
        for (const d of self._deps) {
          result.push(...Dependable.of(d).dependencyRoots);
        }
        return result;
      },
    });

    this.add(...deps);
  }

  /**
   * Add a construct to the dependency roots
   */
  public add(...scopes: IDependable[]) {
    this._deps.push(...scopes);
  }
}

const DEPENDABLE_SYMBOL = Symbol.for('@aws-cdk/core.DependableTrait');

/**
 * Trait for IDependable
 *
 * Traits are interfaces that are privately implemented by objects. Instead of
 * showing up in the public interface of a class, they need to be queried
 * explicitly. This is used to implement certain framework features that are
 * not intended to be used by Construct consumers, and so should be hidden
 * from accidental use.
 *
 * @example
 *
 * // Usage
 * const roots = Dependable.of(construct).dependencyRoots;
 *
 * // Definition
 * Dependable.implement(construct, {
 *       dependencyRoots: [construct],
 * });
 */
export abstract class Dependable {
  /**
   * Turn any object into an IDependable.
   */
  public static implement(instance: IDependable, trait: Dependable) {
    // I would also like to reference classes (to cut down on the list of objects
    // we need to manage), but we can't do that either since jsii doesn't have the
    // concept of a class reference.
    (instance as any)[DEPENDABLE_SYMBOL] = trait;
  }

  /**
   * Return the matching Dependable for the given class instance.
   */
  public static of(instance: IDependable): Dependable {
    const ret = (instance as any)[DEPENDABLE_SYMBOL];
    if (!ret) {
      throw new Error(`${instance} does not implement IDependable. Use "Dependable.implement()" to implement`);
    }
    return ret;
  }

  /**
   * Return the matching Dependable for the given class instance.
   * @deprecated use `of`
   */
  public static get(instance: IDependable): Dependable {
    return this.of(instance);
  }

  /**
   * The set of constructs that form the root of this dependable
   *
   * All resources under all returned constructs are included in the ordering
   * dependency.
   */
  public abstract readonly dependencyRoots: IConstruct[];
}

// tslint:disable-next-line:ban-types
export function captureStackTrace(below?: Function): string[] {
  below = below || captureStackTrace; // hide myself if nothing else
  const object = { stack: '' };
  const previousLimit = Error.stackTraceLimit;
  try {
    Error.stackTraceLimit = Number.MAX_SAFE_INTEGER;
    Error.captureStackTrace(object, below);
  } finally {
    Error.stackTraceLimit = previousLimit;
  }
  if (!object.stack) {
    return [];
  }
  return object.stack.split('\n').slice(1).map(s => s.replace(/^\s*at\s+/, ''));
}

import * as crypto from 'crypto';

/**
 * Resources with this ID are complete hidden from the logical ID calculation.
 */
const HIDDEN_ID = 'Default';

/**
 * Calculates the construct uid based on path components.
 *
 * Components named `Default` (case sensitive) are excluded from uid calculation
 * to allow tree refactorings.
 *
 * @param components path components
 */
export function addressOf(components: string[]) {
  const hash = crypto.createHash('sha1');
  for (const c of components) {
    // skip components called "Default" to enable refactorings
    if (c === HIDDEN_ID) { continue; }

    hash.update(c);
    hash.update('\n');
  }

  // prefix with "c8" so to ensure it starts with non-digit.
  return 'c8' + hash.digest('hex');
}

import * as cdk from 'aws-cdk-lib';
import * as apigw from 'aws-cdk-lib/aws-apigatewayv2';
import { HttpJwtAuthorizer } from 'aws-cdk-lib/aws-apigatewayv2-authorizers';
import { HttpLambdaIntegration } from 'aws-cdk-lib/aws-apigatewayv2-integrations';
import * as events from 'aws-cdk-lib/aws-events';
import * as targets from 'aws-cdk-lib/aws-events-targets';
import * as iam from 'aws-cdk-lib/aws-iam';
import * as lambda from 'aws-cdk-lib/aws-lambda';
import * as nodejs from 'aws-cdk-lib/aws-lambda-nodejs';

import { Construct } from 'constructs';
import * as path from 'path';
import { CrossboxDataStack } from './data-stack';

export interface CrossboxApiStackProps extends cdk.StackProps {
  isTest: boolean;
  dataStack: CrossboxDataStack;
  appDistributionDomainName?: string;
}

export class CrossboxApiStack extends cdk.Stack {
  public readonly httpApi: apigw.HttpApi;
  public readonly stripeEventBus: events.IEventBus;
  public readonly verifyEntryFunction: nodejs.NodejsFunction;

  constructor(scope: Construct, id: string, props: CrossboxApiStackProps) {
    super(scope, id, props);

    const { isTest, dataStack, appDistributionDomainName } = props;
    const { mainTable, entryLogsTable, auditLogsTable, userPool, userPoolClient } = dataStack;

    // --- 1. API Gateway (HTTP) ---
    this.httpApi = new apigw.HttpApi(this, 'HttpApi', {
      corsPreflight: {
        allowOrigins: ['*'],
        allowMethods: [
          apigw.CorsHttpMethod.GET,
          apigw.CorsHttpMethod.POST,
          apigw.CorsHttpMethod.PUT,
          apigw.CorsHttpMethod.DELETE,
          apigw.CorsHttpMethod.OPTIONS,
        ],
        allowHeaders: ['*'],
        maxAge: cdk.Duration.hours(24),
      },
    });

    const jwtAuthorizer = new HttpJwtAuthorizer('CognitoAuthorizer', userPool.userPoolProviderUrl, {
      jwtAudience: [userPoolClient.userPoolClientId],
    });

    // Policy to allow Lambda to read Stripe secret from SSM Parameter Store (if defined)
    const ssmPolicy = new iam.PolicyStatement({
      actions: ['ssm:GetParameter', 'ssm:GetParameters'],
      resources: [`arn:aws:ssm:${this.region}:${this.account}:parameter/crossbox/stripe/*`],
    });

    const commonEnv = {
      MAIN_TABLE_NAME: mainTable.tableName,
      USER_POOL_ID: userPool.userPoolId,
      USER_POOL_CLIENT_ID: userPoolClient.userPoolClientId,
      APP_DISTRIBUTION_DOMAIN_NAME: appDistributionDomainName || '',
    };

    const defaultNodejsFunctionProps: Partial<nodejs.NodejsFunctionProps> = {
      runtime: lambda.Runtime.NODEJS_22_X,
      bundling: {
        minify: true,
        sourceMap: true,
        externalModules: ['@aws-sdk/*'],
      },
    };

    const handlersPath = path.join(__dirname, '..', 'handlers');

    // AuthHandler
    const authHandler = new nodejs.NodejsFunction(this, 'AuthHandler', {
      ...defaultNodejsFunctionProps,
      entry: path.join(handlersPath, 'auth', 'index.ts'),
      memorySize: 256,
      timeout: cdk.Duration.seconds(15),
      environment: {
        ...commonEnv,
      },
    });
    mainTable.grantReadWriteData(authHandler);
    authHandler.addToRolePolicy(
      new iam.PolicyStatement({
        actions: [
          'cognito-idp:AdminCreateUser',
          'cognito-idp:AdminGetUser',
          'cognito-idp:AdminSetUserPassword',
          'cognito-idp:AdminInitiateAuth',
          'cognito-idp:AdminResetUserPassword',
        ],
        resources: [userPool.userPoolArn],
      })
    );
    const authIntegration = new HttpLambdaIntegration('AuthIntegration', authHandler);

    this.httpApi.addRoutes({ path: '/auth/register', methods: [apigw.HttpMethod.POST], integration: authIntegration });
    this.httpApi.addRoutes({ path: '/auth/login', methods: [apigw.HttpMethod.POST], integration: authIntegration });
    this.httpApi.addRoutes({
      path: '/auth/forgot-password',
      methods: [apigw.HttpMethod.POST],
      integration: authIntegration,
    });
    this.httpApi.addRoutes({
      path: '/auth/confirm-forgot-password',
      methods: [apigw.HttpMethod.POST],
      integration: authIntegration,
    });
    this.httpApi.addRoutes({
      path: '/auth/set-password',
      methods: [apigw.HttpMethod.POST],
      integration: authIntegration,
      authorizer: jwtAuthorizer,
    });
    this.httpApi.addRoutes({
      path: '/auth/magic-link',
      methods: [apigw.HttpMethod.POST],
      integration: authIntegration,
    });
    this.httpApi.addRoutes({
      path: '/auth/magic-link/verify',
      methods: [apigw.HttpMethod.GET],
      integration: authIntegration,
    });

    // CheckoutHandler
    const checkoutHandler = new nodejs.NodejsFunction(this, 'CheckoutHandler', {
      ...defaultNodejsFunctionProps,
      entry: path.join(handlersPath, 'checkout', 'index.ts'),
      memorySize: 256,
      timeout: cdk.Duration.seconds(30),
      environment: {
        ...commonEnv,
        STRIPE_SECRET_KEY_SSM_PATH: '/crossbox/stripe/secret-key',
      },
    });
    mainTable.grantReadData(checkoutHandler);
    if (!isTest) {
      checkoutHandler.addToRolePolicy(ssmPolicy);
    }
    const checkoutIntegration = new HttpLambdaIntegration('CheckoutIntegration', checkoutHandler);
    this.httpApi.addRoutes({
      path: '/checkout/session',
      methods: [apigw.HttpMethod.POST],
      integration: checkoutIntegration,
    });

    // StripeWebhookHandler
    const stripeWebhookHandler = new nodejs.NodejsFunction(this, 'StripeWebhookHandler', {
      ...defaultNodejsFunctionProps,
      entry: path.join(handlersPath, 'stripe-webhook', 'index.ts'),
      memorySize: 256,
      timeout: cdk.Duration.seconds(30),
      environment: {
        ...commonEnv,
        STRIPE_SECRET_KEY_SSM_PATH: '/crossbox/stripe/secret-key',
      },
    });
    mainTable.grantReadWriteData(stripeWebhookHandler);
    stripeWebhookHandler.addToRolePolicy(
      new iam.PolicyStatement({
        actions: ['cognito-idp:AdminCreateUser', 'cognito-idp:AdminGetUser', 'cognito-idp:AdminResetUserPassword'],
        resources: [userPool.userPoolArn],
      })
    );
    if (!isTest) {
      stripeWebhookHandler.addToRolePolicy(ssmPolicy);
    }

    // EventBridge Bus & Rule for Stripe Events
    const partnerBusName = this.node.tryGetContext('stripePartnerBusName') || process.env.STRIPE_PARTNER_BUS_NAME;

    this.stripeEventBus = partnerBusName
      ? events.EventBus.fromEventBusName(this, 'StripeEventBus', partnerBusName)
      : new events.EventBus(this, 'StripeEventBus', {
          eventBusName: isTest ? `${this.stackName}-StripeBus` : 'stripe-events-bus',
        });

    const stripeEventRule = new events.Rule(this, 'StripeEventRule', {
      eventBus: this.stripeEventBus,
      eventPattern: {
        detailType: [
          'checkout.session.completed',
          'customer.subscription.updated',
          'customer.subscription.deleted',
          'invoice.paid',
          'invoice.payment_failed',
        ],
      },
    });
    stripeEventRule.addTarget(new targets.LambdaFunction(stripeWebhookHandler));

    // MemberHandler
    const memberHandler = new nodejs.NodejsFunction(this, 'MemberHandler', {
      ...defaultNodejsFunctionProps,
      entry: path.join(handlersPath, 'member', 'index.ts'),
      memorySize: 256,
      timeout: cdk.Duration.seconds(30),
      environment: {
        ...commonEnv,
        STRIPE_SECRET_KEY_SSM_PATH: '/crossbox/stripe/secret-key',
      },
    });
    mainTable.grantReadWriteData(memberHandler);
    memberHandler.addToRolePolicy(ssmPolicy);

    const memberIntegration = new HttpLambdaIntegration('MemberIntegration', memberHandler);

    this.httpApi.addRoutes({
      path: '/member/dashboard',
      methods: [apigw.HttpMethod.GET],
      integration: memberIntegration,
      authorizer: jwtAuthorizer,
    });
    this.httpApi.addRoutes({
      path: '/member/consent',
      methods: [apigw.HttpMethod.POST],
      integration: memberIntegration,
      authorizer: jwtAuthorizer,
    });
    this.httpApi.addRoutes({
      path: '/member/qr',
      methods: [apigw.HttpMethod.POST],
      integration: memberIntegration,
      authorizer: jwtAuthorizer,
    });
    this.httpApi.addRoutes({
      path: '/member/portal-session',
      methods: [apigw.HttpMethod.POST],
      integration: memberIntegration,
      authorizer: jwtAuthorizer,
    });
    this.httpApi.addRoutes({
      path: '/member/invoices',
      methods: [apigw.HttpMethod.GET],
      integration: memberIntegration,
      authorizer: jwtAuthorizer,
    });

    // VerifyEntry
    this.verifyEntryFunction = new nodejs.NodejsFunction(this, 'VerifyEntry', {
      ...defaultNodejsFunctionProps,
      entry: path.join(handlersPath, 'verify-entry', 'index.ts'),
      memorySize: 1024,
      timeout: cdk.Duration.seconds(10),
      environment: {
        ...commonEnv,
        ENTRY_LOGS_TABLE_NAME: entryLogsTable.tableName,
        LOCKER_CLIENT_TYPE: isTest ? 'mock' : 'mqtt',
        SSM_IOT_ENDPOINT_PARAM: '/crossbox/iot/endpoint',
        SSM_LOCKER_THING_NAME_PARAM: '/crossbox/iot/locker-thing-name',
      },
    });
    mainTable.grantReadWriteData(this.verifyEntryFunction);
    entryLogsTable.grantReadWriteData(this.verifyEntryFunction);
    this.verifyEntryFunction.addToRolePolicy(
      new iam.PolicyStatement({
        actions: ['iot:Publish', 'iot:DescribeEndpoint'],
        resources: ['*'],
      })
    );
    this.verifyEntryFunction.addToRolePolicy(
      new iam.PolicyStatement({
        actions: ['ssm:GetParameter', 'ssm:GetParameters'],
        resources: [`arn:aws:ssm:${this.region}:${this.account}:parameter/crossbox/iot/*`],
      })
    );

    // AdminHandler
    const adminHandler = new nodejs.NodejsFunction(this, 'AdminHandler', {
      ...defaultNodejsFunctionProps,
      entry: path.join(handlersPath, 'admin', 'index.ts'),
      memorySize: 256,
      timeout: cdk.Duration.seconds(30),
      environment: {
        ...commonEnv,
        AUDIT_LOGS_TABLE_NAME: auditLogsTable.tableName,
        ENTRY_LOGS_TABLE_NAME: entryLogsTable.tableName,
      },
    });
    mainTable.grantReadWriteData(adminHandler);
    auditLogsTable.grantWriteData(adminHandler);
    entryLogsTable.grantReadData(adminHandler);
    adminHandler.addToRolePolicy(
      new iam.PolicyStatement({
        actions: ['iot:Publish', 'iot:DescribeEndpoint'],
        resources: ['*'],
      })
    );

    const adminIntegration = new HttpLambdaIntegration('AdminIntegration', adminHandler);
    const adminRoutes = [
      { path: '/admin/locations', methods: [apigw.HttpMethod.GET, apigw.HttpMethod.POST] },
      { path: '/admin/locations/{id}', methods: [apigw.HttpMethod.PUT, apigw.HttpMethod.DELETE] },
      { path: '/admin/locations/{id}/activity', methods: [apigw.HttpMethod.GET] },
      { path: '/admin/locations/{id}/scanners', methods: [apigw.HttpMethod.GET, apigw.HttpMethod.POST] },
      { path: '/admin/locations/{id}/devices', methods: [apigw.HttpMethod.GET, apigw.HttpMethod.POST] },
      { path: '/admin/devices/{id}', methods: [apigw.HttpMethod.PUT, apigw.HttpMethod.DELETE] },
      { path: '/admin/members', methods: [apigw.HttpMethod.GET] },
      { path: '/admin/members/{id}', methods: [apigw.HttpMethod.GET] },
      { path: '/admin/members/{id}/override', methods: [apigw.HttpMethod.POST] },
      { path: '/admin/devices/{id}/unlock', methods: [apigw.HttpMethod.POST] },
      { path: '/admin/hmac/rotate', methods: [apigw.HttpMethod.POST] },
    ];
    for (const route of adminRoutes) {
      this.httpApi.addRoutes({
        path: route.path,
        methods: route.methods,
        integration: adminIntegration,
        authorizer: jwtAuthorizer,
      });
    }

    // GraceExpiryCron Lambda
    const graceExpiryHandler = new nodejs.NodejsFunction(this, 'GraceExpiryCron', {
      ...defaultNodejsFunctionProps,
      entry: path.join(handlersPath, 'grace-expiry-cron', 'index.ts'),
      memorySize: 256,
      timeout: cdk.Duration.seconds(30),
      environment: commonEnv,
    });
    mainTable.grantReadWriteData(graceExpiryHandler);

    new events.Rule(this, 'GraceExpiryCronSchedule', {
      schedule: events.Schedule.rate(cdk.Duration.hours(1)),
      targets: [new targets.LambdaFunction(graceExpiryHandler)],
    });

    // Outputs
    new cdk.CfnOutput(this, 'ApiUrl', {
      value: this.httpApi.apiEndpoint,
      description: 'API Gateway Endpoint URL',
    });
  }
}

import * as cdk from 'aws-cdk-lib';
import * as iam from 'aws-cdk-lib/aws-iam';
import * as iot from 'aws-cdk-lib/aws-iot';
import * as lambda from 'aws-cdk-lib/aws-lambda';
import * as secretsmanager from 'aws-cdk-lib/aws-secretsmanager';
import * as ssm from 'aws-cdk-lib/aws-ssm';
import * as cr from 'aws-cdk-lib/custom-resources';
import { Construct } from 'constructs';
import { CrossboxApiStack } from './api-stack';

export interface CrossboxIotStackProps extends cdk.StackProps {
  isTest: boolean;
  apiStack: CrossboxApiStack;
}

export class CrossboxIotStack extends cdk.Stack {
  public readonly certSecret: secretsmanager.Secret;
  public readonly iotThing: iot.CfnThing;
  public readonly lockerThing: iot.CfnThing;
  public readonly iotPolicy: iot.CfnPolicy;
  public readonly topicRule: iot.CfnTopicRule;

  constructor(scope: Construct, id: string, props: CrossboxIotStackProps) {
    super(scope, id, props);

    const { isTest, apiStack } = props;

    const thingName = this.node.tryGetContext('thing_name') || 'crossbox-qr-scanner-01';
    const lockThingName = this.node.tryGetContext('lock_thing_name') || 'crossbox-locker-relay-01';
    const policyName = this.node.tryGetContext('policy_name') || 'crossbox-gym-iot-policy';
    const secretName = this.node.tryGetContext('secret_name') || 'crossbox-gym/iot/certs';

    // 1a. Create AWS IoT Thing for QR Scanner
    this.iotThing = new iot.CfnThing(this, 'QrScannerThing', {
      thingName,
      attributePayload: {
        attributes: {
          device_type: 'HDWR-HD360-QR-Scanner',
          version: '1.0.0',
        },
      },
    });

    // 1b. Create AWS IoT Thing for Lock (Shelly Plus 1 Mini Gen3)
    this.lockerThing = new iot.CfnThing(this, 'LockerThing', {
      thingName: lockThingName,
      attributePayload: {
        attributes: {
          device_type: 'Shelly-Plus-1-Mini-Gen3',
          version: '1.0.0',
        },
      },
    });

    // 2. Create AWS IoT Policy
    const iotPolicyDocument = {
      Version: '2012-10-17',
      Statement: [
        {
          Effect: 'Allow',
          Action: ['iot:Connect'],
          Resource: [
            `arn:aws:iot:${this.region}:${this.account}:client/${thingName}`,
            `arn:aws:iot:${this.region}:${this.account}:client/${lockThingName}`,
            `arn:aws:iot:${this.region}:${this.account}:client/*`,
          ],
        },
        {
          Effect: 'Allow',
          Action: ['iot:Publish'],
          Resource: [`arn:aws:iot:${this.region}:${this.account}:topic/gym/scanners/*/scan`],
        },
        {
          Effect: 'Allow',
          Action: ['iot:Subscribe'],
          Resource: [
            `arn:aws:iot:${this.region}:${this.account}:topicfilter/gym/scanners/*/feedback`,
            `arn:aws:iot:${this.region}:${this.account}:topicfilter/gym/lockers/*/command`,
          ],
        },
        {
          Effect: 'Allow',
          Action: ['iot:Receive'],
          Resource: [
            `arn:aws:iot:${this.region}:${this.account}:topic/gym/scanners/*/feedback`,
            `arn:aws:iot:${this.region}:${this.account}:topic/gym/lockers/*/command`,
          ],
        },
      ],
    };

    this.iotPolicy = new iot.CfnPolicy(this, 'CrossboxIotPolicy', {
      policyName,
      policyDocument: iotPolicyDocument,
    });

    // 3. Secrets Manager Secret for storing X.509 Certs & Keys
    this.certSecret = new secretsmanager.Secret(this, 'CrossboxIotCertSecret', {
      secretName,
      description:
        'mTLS X.509 Device Certificate & Private Key for Crossbox Gym IoT devices (QR Scanner and Shelly Lock Relay)',
      removalPolicy: isTest ? cdk.RemovalPolicy.DESTROY : cdk.RemovalPolicy.RETAIN,
    });

    // 4. Lambda Custom Resource to generate IoT Certs & store in Secrets Manager
    const certProvisionerLambda = new lambda.Function(this, 'CertProvisionerHandler', {
      runtime: lambda.Runtime.PYTHON_3_11,
      handler: 'index.on_event',
      code: lambda.Code.fromInline(this._getLambdaCode()),
      description: 'Custom Resource Lambda generating AWS IoT Keys/Certs and storing in Secrets Manager',
      timeout: cdk.Duration.seconds(60),
    });

    // IAM permissions for Lambda
    certProvisionerLambda.addToRolePolicy(
      new iam.PolicyStatement({
        actions: [
          'iot:CreateKeysAndCertificate',
          'iot:UpdateCertificate',
          'iot:DeleteCertificate',
          'iot:AttachPolicy',
          'iot:DetachPolicy',
          'iot:AttachThingPrincipal',
          'iot:DetachThingPrincipal',
          'iot:DescribeEndpoint',
        ],
        resources: ['*'],
      })
    );

    this.certSecret.grantWrite(certProvisionerLambda);

    const certProvider = new cr.Provider(this, 'CertProvisionerProvider', {
      onEventHandler: certProvisionerLambda,
    });

    const customResource = new cdk.CustomResource(this, 'CertProvisionerResource', {
      serviceToken: certProvider.serviceToken,
      properties: {
        ThingName: thingName,
        PolicyName: policyName,
        SecretArn: this.certSecret.secretArn,
      },
    });

    customResource.node.addDependency(this.iotThing);
    customResource.node.addDependency(this.lockerThing);
    customResource.node.addDependency(this.iotPolicy);

    // 5. AWS IoT Topic Rule to invoke VerifyEntry Lambda on incoming scans
    const verifyEntryFunc = apiStack.verifyEntryFunction;

    this.topicRule = new iot.CfnTopicRule(this, 'CrossboxQrScannerScanRule', {
      ruleName: 'CrossboxQrScannerScanRule',
      topicRulePayload: {
        sql: "SELECT *, topic(3) as scannerId FROM 'gym/scanners/+/scan'",
        description: 'Forwards MQTT scan events from RPi QR scanner to VerifyEntry Lambda',
        actions: [
          {
            lambda: {
              functionArn: verifyEntryFunc.functionArn,
            },
          },
        ],
        ruleDisabled: false,
      },
    });

    // Grant IoT permission to invoke VerifyEntry Lambda
    verifyEntryFunc.addPermission('IoTInvokePermission', {
      principal: new iam.ServicePrincipal('iot.amazonaws.com'),
      sourceArn: `arn:aws:iot:${this.region}:${this.account}:rule/CrossboxQrScannerScanRule`,
    });

    // SSM Parameter Store Parameters for runtime dynamic lookup
    new ssm.StringParameter(this, 'IotEndpointParameter', {
      parameterName: '/crossbox/iot/endpoint',
      stringValue: customResource.getAttString('IotEndpoint'),
      description: 'AWS IoT Core ATS Data Endpoint URL for Crossbox Gym',
    });

    new ssm.StringParameter(this, 'LockerThingNameParameter', {
      parameterName: '/crossbox/iot/locker-thing-name',
      stringValue: lockThingName,
      description: 'AWS IoT Locker Relay Thing Name for Crossbox Gym',
    });

    // Stack Outputs
    new cdk.CfnOutput(this, 'SecretNameOutput', {
      value: secretName,
      description: 'AWS Secrets Manager Secret Name for fetching certificates',
    });

    new cdk.CfnOutput(this, 'ThingNameOutput', {
      value: thingName,
      description: 'AWS IoT QR Scanner Thing Name',
    });

    new cdk.CfnOutput(this, 'LockerThingNameOutput', {
      value: lockThingName,
      description: 'AWS IoT Lock Thing Name (Shelly Plus 1 Mini Gen3)',
    });

    new cdk.CfnOutput(this, 'IotEndpointOutput', {
      value: customResource.getAttString('IotEndpoint'),
      description: 'AWS IoT Core ATS Endpoint URL',
    });

    new cdk.CfnOutput(this, 'IotEndpoint', {
      value: customResource.getAttString('IotEndpoint'),
      description: 'AWS IoT Core ATS Endpoint URL',
    });

    new cdk.CfnOutput(this, 'SecretName', {
      value: secretName,
      description: 'AWS Secrets Manager Secret Name for fetching certificates',
    });

    new cdk.CfnOutput(this, 'ScannerClientId', {
      value: thingName,
      description: 'AWS IoT QR Scanner Client ID / Thing Name',
    });

    new cdk.CfnOutput(this, 'LockerClientId', {
      value: lockThingName,
      description: 'AWS IoT Lock Relay Client ID / Thing Name',
    });

    new cdk.CfnOutput(this, 'ScannerScanTopic', {
      value: `gym/scanners/${thingName}/scan`,
      description: 'MQTT topic for QR scanner to publish scan payloads',
    });

    new cdk.CfnOutput(this, 'ScannerFeedbackTopic', {
      value: `gym/scanners/${thingName}/feedback`,
      description: 'MQTT topic for QR scanner to subscribe for access feedback',
    });

    new cdk.CfnOutput(this, 'LockerCommandTopic', {
      value: `gym/lockers/${lockThingName}/command`,
      description: 'MQTT topic for locker relay to subscribe for unlock commands',
    });

    new cdk.CfnOutput(this, 'ScannerCertPath', {
      value: `certs/${thingName}/`,
      description: 'Local directory path for fetched scanner certificates',
    });

    new cdk.CfnOutput(this, 'LockerCertPath', {
      value: `certs/${lockThingName}/`,
      description: 'Local directory path for fetched locker certificates',
    });
  }

  private _getLambdaCode(): string {
    return `import json
import urllib.request
import boto3

iot = boto3.client('iot')
secretsmanager = boto3.client('secretsmanager')

def fetch_amazon_root_ca():
    url = "https://www.amazontrust.com/repository/AmazonRootCA1.pem"
    req = urllib.request.Request(url, headers={"User-Agent": "CDKCertProvisioner/1.0"})
    with urllib.request.urlopen(req, timeout=10) as resp:
        return resp.read().decode("utf-8")

def on_event(event, context):
    request_type = event['RequestType']
    props = event['ResourceProperties']
    thing_name = props['ThingName']
    policy_name = props['PolicyName']
    secret_arn = props['SecretArn']

    if request_type == 'Create':
        ep_resp = iot.describe_endpoint(endpointType='iot:Data-ATS')
        endpoint_url = ep_resp.get('endpointAddress')

        cert_resp = iot.create_keys_and_certificate(setAsActive=True)
        cert_arn = cert_resp['certificateArn']
        cert_id = cert_resp['certificateId']
        cert_pem = cert_resp['certificatePem']
        private_key = cert_resp['keyPair']['PrivateKey']
        root_ca = fetch_amazon_root_ca()

        iot.attach_policy(policyName=policy_name, target=cert_arn)
        iot.attach_thing_principal(thingName=thing_name, principal=cert_arn)

        secret_payload = {
            "certificate_pem": cert_pem,
            "private_key": private_key,
            "root_ca": root_ca,
            "certificate_arn": cert_arn,
            "certificate_id": cert_id,
            "endpoint_address": endpoint_url
        }
        secretsmanager.put_secret_value(
            SecretId=secret_arn,
            SecretString=json.dumps(secret_payload)
        )

        return {
            'PhysicalResourceId': cert_id,
            'Data': {
                'CertificateArn': cert_arn,
                'CertificateId': cert_id,
                'IotEndpoint': endpoint_url
            }
        }

    elif request_type == 'Update':
        physical_id = event['PhysicalResourceId']
        ep_resp = iot.describe_endpoint(endpointType='iot:Data-ATS')
        return {
            'PhysicalResourceId': physical_id,
            'Data': {
                'IotEndpoint': ep_resp.get('endpointAddress')
            }
        }

    elif request_type == 'Delete':
        physical_id = event.get('PhysicalResourceId')
        if physical_id:
            try:
                cert_arn = f"arn:aws:iot:{boto3.session.Session().region_name}:{boto3.client('sts').get_caller_identity()['Account']}:cert/{physical_id}"
                try:
                    iot.detach_policy(policyName=policy_name, target=cert_arn)
                except Exception:
                    pass
                try:
                    iot.detach_thing_principal(thingName=thing_name, principal=cert_arn)
                except Exception:
                    pass
                try:
                    iot.update_certificate(certificateId=physical_id, newStatus='INACTIVE')
                    iot.delete_certificate(certificateId=physical_id, forceDelete=True)
                except Exception:
                    pass
            except Exception as e:
                print(f"Error during cert cleanup: {e}")

        return {'PhysicalResourceId': physical_id}
`;
  }
}

