    for (const dir of TEMPORARY_ASSEMBLY_DIRS) {
      fs.rmSync(dir, { recursive: true, force: true });
    }
    TEMPORARY_ASSEMBLY_DIRS.splice(0, TEMPORARY_ASSEMBLY_DIRS.length);
  }

