/**
 * Returns a copy of `obj` without undefined values in maps or arrays.
 */
function filterUndefined(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.filter(x => x !== undefined).map(x => filterUndefined(x));
  }

  if (typeof(obj) === 'object') {
    const ret: any = { };
    for (const [key, value] of Object.entries(obj)) {
      if (value === undefined) {
        continue;
      }
      ret[key] = filterUndefined(value);
    }
    return ret;
  }

  return obj;
}

function ignore(_x: any) {
  return;
}

/**
 * Turn the given optional output directory into a fixed output directory
 */
function determineOutputDirectory(outdir?: string) {
  if (outdir) {
    return outdir;
  }

  // Make a temporary directory; clean it up automatically if this is done for testing.
  const tmpDir = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), 'cdk.out'));
  TEMPORARY_ASSEMBLY_DIRS.push(tmpDir);
  return outdir ?? tmpDir;
}

function ensureDirSync(dir: string) {
  if (fs.existsSync(dir)) {
    if (!fs.statSync(dir).isDirectory()) {
      throw new CloudAssemblyError(`${dir} must be a directory`);
    }
  } else {
    fs.mkdirSync(dir, { recursive: true });
  }
}

// On process exit, delete all temporary assembly directories
const TEMPORARY_ASSEMBLY_DIRS: string[] = [];
process.on('exit', () => CloudAssembly.cleanupTemporaryDirectories());

import { CloudAssemblyError } from './error';

export type KeyFunc<T> = (x: T) => string;
export type DepFunc<T> = (x: T) => string[];

/**
 * Return a topological sort of all elements of xs, according to the given dependency functions
 *
 * Dependencies outside the referenced set are ignored.
 *
 * Not a stable sort, but in order to keep the order as stable as possible, we'll sort by key
 * among elements of equal precedence.
 */
export function topologicalSort<T>(xs: Iterable<T>, keyFn: KeyFunc<T>, depFn: DepFunc<T>): T[] {
  const remaining = new Map<string, TopoElement<T>>();
  for (const element of xs) {
    const key = keyFn(element);
    remaining.set(key, { key, element, dependencies: depFn(element) });
  }

  const ret = new Array<T>();
  while (remaining.size > 0) {
    // All elements with no more deps in the set can be ordered
    const selectable = Array.from(remaining.values()).filter(e => e.dependencies.every(d => !remaining.has(d)));

    selectable.sort((a, b) => a.key < b.key ? -1 : b.key < a.key ? 1 : 0);

    for (const selected of selectable) {
      ret.push(selected.element);
      remaining.delete(selected.key);
    }

    // If we didn't make any progress, we got stuck
    if (selectable.length === 0) {
      throw new CloudAssemblyError(`Could not determine ordering between: ${Array.from(remaining.keys()).join(', ')}`);
    }
  }

  return ret;
}

interface TopoElement<T> {
  key: string;
  dependencies: string[];
  element: T;
}

